-- PT108-S3-Q25. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT108-S3-Q25$batch05$ AND q.stimulus=$batch05$Anthropologist: After mapping the complete dominance hierarchy for a troupe of vervet monkeys by examining their pairwise interaction, we successfully predicted more complex forms of their group behavior by assuming that each monkey had knowledge of the complete hierarchy. Since our prediction was so accurate, it follows that the assumption we used to reach it was in fact true.

Primatologist: Although I agree that your assumption helped you make those predictions, your conclusion does not follow. You might as well argue that since we can predict the output of some bank cash machines by assuming that these machines actually want to satisfy the customers' requests, these cash machines must really have desires.$batch05$ AND q.prompt=$batch05$The primatologist uses which one of the following argumentative techniques in countering the anthropologist's argument?$batch05$ AND q.correct_choice=$batch05$C$batch05$) THEN RAISE EXCEPTION 'Question changed: PT108-S3-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT108-S3-Q25$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT108-S3-Q25'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT108-S3-Q25$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$(Primatologist) The anthropologist's conclusion does not follow.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$By the same logic, since assuming cash machines "want" to satisfy customers helps predict their behavior, cash machines would really have desires.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The anthropologist reasons: an assumption made accurate predictions, so the assumption is true. The primatologist runs that exact step on cash machines and reaches something absurd. A useful assumption is not necessarily a true one.$batch05$), (3, $batch05$Goal$batch05$, $batch05$Using the same reasoning step in another argument to show it leads somewhere absurd.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT108-S3-Q25$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$The primatologist offers no facts that are inconsistent with the conclusion. The response is an argument of the same shape.$batch05$), ($batch05$B$batch05$, $batch05$The cash machine argument does not start by denying that monkeys know the hierarchy.$batch05$), ($batch05$C$batch05$, $batch05$The step is "accurate prediction, so the assumption is true." The other argument is the cash machines. The absurd conclusion is that they have desires.$batch05$), ($batch05$D$batch05$, $batch05$This is the most popular wrong answer. But the primatologist never says the anthropologist is ignorant of anything. The analogy shows a flaw in the reasoning, not in the person.$batch05$), ($batch05$E$batch05$, $batch05$No scientific term is misread.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT108-S3-Q25$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
